script:
"=== installing OpenCode ==="
try {
  irm https://opencode.ai/install.ps1 | iex
  "install script done"
} catch {
  "INSTALL FAILED: " + $_.Exception.Message
  exit 1
}
Start-Sleep -Seconds 3
"=== verifying ==="
$oc = Get-Command opencode -ErrorAction SilentlyContinue
if ($oc) {
  "found at: $($oc.Source)"
  try { opencode --version } catch { "version check failed" }
} else {
  "opencode not in PATH, checking common locations"
  Get-ChildItem "$env:USERPROFILE\.opencode" -ErrorAction SilentlyContinue | Select-Object Name
  Get-ChildItem "$env:LOCALAPPDATA\opencode" -ErrorAction SilentlyContinue | Select-Object Name
}
